let quotationCustomers=[];
async function loadCustomers(){const picker=document.querySelector('#quotationCustomer');if(!picker)return;try{quotationCustomers=await api('rentcam_contacts?select=*&kind=eq.customer&order=name.asc');const phoneKey=p=>String(p||'').replace(/\D/g,'').replace(/^62/,'0'),known=new Set(quotationCustomers.map(c=>phoneKey(c.phone)).filter(Boolean));orders.filter(o=>o.source!=='quotation'&&o.rental_status!=='cancelled').forEach(o=>{const key=phoneKey(o.phone);if(key&&!known.has(key)){known.add(key);quotationCustomers.push({id:'order-'+o.id,name:o.customer_name,phone:o.phone,email:o.email,company:''})}});if(!picker.isConnected)return;picker.innerHTML='<option value="">Customer baru / input manual</option>'+quotationCustomers.map(c=>`<option value="${E(c.id)}">${E(c.name)}${c.company?' · '+E(c.company):''}${c.phone?' · '+E(c.phone):''}</option>`).join('');document.querySelector('#quotationCustomerInfo').textContent=quotationCustomers.length+' customer dari Master Data. Pilih untuk mengisi kontak otomatis.'}catch(e){if(picker.isConnected)document.querySelector('#quotationCustomerInfo').textContent=e.message}}
async function loadProducts(){const f=document.querySelector('#proDirectForm');if(!f)return;try{const data=await rpc('rentcam_admin_stock',{p_start:f.elements.start.value,p_end:f.elements.end.value,p_exclude:null});if(!f.isConnected)return;stock=data;f.querySelectorAll('[data-item]').forEach(select=>{const value=select.value;select.innerHTML='<option value="">Pilih produk dari master</option>'+stock.map(p=>'<option value="'+E(p.id)+'">'+E(p.name)+' · tersedia '+p.available+'</option>').join('');select.value=value});if(!f.querySelector('.pro-item-row'))addItem();estimate()}catch(e){f.querySelector('[data-msg]').textContent=e.message}}function addItem(){document.querySelector('#proItemRows')?.insertAdjacentHTML('beforeend',`<tr class="pro-item-row"><td data-row-number></td><td><select data-item required><option value="">Pilih produk dari master</option>${stock.map(p=>`<option value="${E(p.id)}">${E(p.name)} · tersedia ${p.available}</option>`).join('')}</select></td><td><input data-quantity type="number" min="1" max="100" value="1" required aria-label="Jumlah produk"></td><td data-row-days>1</td><td data-row-price>Rp0</td><td data-row-amount>Rp0</td><td>${B('remove-item','×')}</td></tr>`);estimate()}
function estimate(){const f=document.querySelector('#proDirectForm');if(!f)return;const days=Math.max(0,Math.round((new Date(f.elements.end.value)-new Date(f.elements.start.value))/86400000)+1),rows=[...f.querySelectorAll('.pro-item-row')];let subtotal=0;rows.forEach((r,i)=>{const p=stock.find(p=>p.id===r.querySelector('[data-item]').value),price=Number(p?.price||0),qty=Number(r.querySelector('[data-quantity]').value||0),amount=price*qty*days;subtotal+=amount;r.querySelector('[data-row-number]').textContent=i+1;r.querySelector('[data-row-days]').textContent=days;r.querySelector('[data-row-price]').textContent=M(price);r.querySelector('[data-row-amount]').textContent=M(amount)});f.querySelector('#quotationDays').textContent=days+' hari';f.querySelector('#quotationSubtotal').textContent=M(subtotal)}
function documentView(id){const d=docs.find(d=>d.id===id),o=orders.find(o=>o.id===d?.order_id);if(!o)return;const cfg=window.RENTCAM_CMS_CONFIG||{},g=cfg.general||{};document.querySelector('#proDocumentHost').innerHTML=`<div class="pro-card">${B('print','Cetak / Simpan PDF')}<div id="proPrintable"><header class="pro-doc-head"><div><h2>${E(g.siteName||'Rentcam')}</h2><p>${E(g.tagline)}<br>${E(g.email)} ${E(g.whatsapp)}</p></div><div><h1>${d.kind==='invoice'?'INVOICE':'PENAWARAN'}</h1><strong>${E(d.number)}</strong><p>${E(d.issued_on)}</p></div></header><div class="pro-doc-customer"><p><strong>Customer:</strong> ${E(o.customer_name)}<br>WhatsApp: ${E(o.phone)}<br>Email: ${E(o.email)}</p><p><strong>Periode sewa:</strong> ${E(o.start_date)} — ${E(o.end_date)}<br>Referensi: ${E(o.order_number)}${d.valid_until?'<br>Berlaku sampai: '+E(d.valid_until):''}</p></div><table><thead><tr><th>No.</th><th>Equipment</th><th>Qty</th><th>Hari</th><th>Harga/hari</th><th>Jumlah</th></tr></thead><tbody>${o.items.map((i,n)=>`<tr><td>${n+1}</td><td>${E(i.name)}</td><td>${i.quantity}</td><td>${i.days}</td><td>${M(i.price_per_day)}</td><td>${M(i.amount)}</td></tr>`).join('')}</tbody></table><div class="pro-doc-total"><p>Total <strong>${M(o.total)}</strong></p>${d.kind==='invoice'?`<p>Sudah bayar ${M(o.paid_amount)}</p><p>Sisa pembayaran <strong>${M(Math.max(0,o.total-o.paid_amount))}</strong></p>`:''}</div><p>Catatan: ${E(d.notes)}</p><p>Alamat antar–jemput: ${E(o.delivery?.address||'Ambil / kembali sendiri')}</p><p>${d.kind==='quotation'?'Penawaran belum mengunci ketersediaan alat. Konfirmasi stok dan pembayaran diperlukan sebelum persetujuan rental.':'Pembayaran berdasarkan nominal yang sudah diverifikasi admin.'}</p><p>${E(o.bank_account?.bank)} ${E(o.bank_account?.number)} ${E(o.bank_account?.holder)}</p></div></div>`}
function report(){const f=document.querySelector('#proReportForm');if(!f)return;const start=f.elements.start.value,end=f.elements.end.value;if(end<start){document.querySelector('#proReportHost').textContent='Periksa periode tanggal.';return}const ids=new Set(entries.filter(j=>j.entry_date>=start&&j.entry_date<=end).map(j=>j.id)),period=lines.filter(l=>ids.has(l.entry_id)),revenue=period.filter(l=>l.account_code.startsWith('4')).reduce((s,l)=>s+Number(l.credit)-Number(l.debit),0),expense=period.filter(l=>l.account_code.startsWith('5')).reduce((s,l)=>s+Number(l.debit)-Number(l.credit),0),cashIn=period.filter(l=>l.account_code==='1000').reduce((s,l)=>s+Number(l.debit),0),cashOut=period.filter(l=>l.account_code==='1000').reduce((s,l)=>s+Number(l.credit),0),upTo=new Set(entries.filter(j=>j.entry_date<=end).map(j=>j.id)),balances={};lines.filter(l=>upTo.has(l.entry_id)).forEach(l=>{balances[l.account_code]??={name:l.account_name,balance:0};balances[l.account_code].balance+=Number(l.debit)-Number(l.credit)});document.querySelector('#proReportHost').innerHTML=stats([['Pendapatan diakui',M(revenue)],['Beban',M(expense)],['Laba / rugi periode',M(revenue-expense)],['Arus kas bersih',M(cashIn-cashOut)]])+`<div class="pro-card"><h3>Neraca saldo sampai ${E(end)}</h3><div class="pro-table"><table><thead><tr><th>Akun</th><th>Debit</th><th>Kredit</th></tr></thead><tbody>${Object.entries(balances).sort().map(([code,b])=>`<tr><td>${code} · ${E(b.name)}</td><td>${M(Math.max(0,b.balance))}</td><td>${M(Math.max(0,-b.balance))}</td></tr>`).join('')}</tbody></table></div><p>Kas masuk ${M(cashIn)} · Kas keluar ${M(cashOut)}. Pendapatan rental diakui ketika invoice diterbitkan.</p></div>`}
document.addEventListener('click',async e=>{const nav=e.target.closest('[data-pro-nav],[data-nav],[data-rental-nav]');if(nav){if(nav.dataset.proNav||nav.dataset.nav==='dashboard'){e.preventDefault();e.stopImmediatePropagation();open(nav.dataset.proNav||'dashboard')}else{page='';document.querySelector('.v5-actions [data-act=save]')?.removeAttribute('hidden')}return}const b=e.target.closest('[data-pro-action]');if(!b)return;e.preventDefault();const a=b.dataset.proAction,id=b.dataset.id;if(a==='new-order'){open('direct');return}if(a==='new-quote'){document.querySelector('.v5-content').innerHTML='<div class="pro-system">'+orderForm(true)+'</div>';loadProducts();loadCustomers();return}if(a.startsWith('go-')){open(a.slice(3));return}if(a==='add-item'){addItem();return}if(a==='remove-item'){b.closest('.pro-item-row').remove();estimate();return}if(a==='document'){documentView(id);return}if(a==='print'){const sheet=document.createElement('section');sheet.id='proPrintSheet';sheet.innerHTML=document.querySelector('#proPrintable').innerHTML;document.body.append(sheet);document.body.classList.add('pro-printing');window.print();document.body.classList.remove('pro-printing');sheet.remove();return}if(a==='export-journal'){const rows=[['Tanggal','Referensi','Kode Akun','Akun','Debit','Kredit'],...entries.flatMap(j=>lines.filter(l=>l.entry_id===j.id).map(l=>[j.entry_date,j.description,l.account_code,l.account_name,l.debit,l.credit]))];const csv='\uFEFF'+rows.map(row=>row.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='jurnal-rental.csv';a.click();URL.revokeObjectURL(url);return}if(a==='convert'&&!working){if(!confirm('Jadikan penawaran ini sebagai pesanan rental?'))return;working=true;try{await act('convert',{order_id:id});await open('quotations')}catch(e){alert(e.message)}finally{working=false}}},true);
document.addEventListener('submit',async e=>{const f=e.target;if(!['proStockForm','proDirectForm','proInvoiceForm','proReportForm'].includes(f.id))return;e.preventDefault();if(f.id==='proReportForm'){report();return}if(working)return;working=true;const b=f.querySelector('[type=submit]');b.disabled=true;const msg=f.querySelector('[data-msg]');try{const d=Object.fromEntries(new FormData(f));if(f.id==='proStockForm'){const xs=await rpc('rentcam_admin_stock',{p_start:d.start,p_end:d.end,p_exclude:null});document.querySelector('#proStockResult').innerHTML=`<div class="pro-card"><h3>${xs.length} produk</h3><div class="pro-table"><table><thead><tr><th>Produk</th><th>Brand</th><th>Total stok</th><th>Terpakai</th><th>Tersedia</th></tr></thead><tbody>${xs.map(p=>`<tr><td>${E(p.name)}</td><td>${E(p.brand)}</td><td>${p.stock}</td><td>${p.reserved}</td><td><strong class="${p.available?'pro-green':'pro-red'}">${p.available}</strong></td></tr>`).join('')}</tbody></table></div></div>`}else if(f.id==='proInvoiceForm'){await act('invoice',{order_id:d.order_id});await open('invoices')}else{const phone=d.phone.replace(/[^0-9+]/g,'');if(!/^\+?[0-9]{8,16}$/.test(phone))throw Error('Isi WhatsApp yang valid.');const items=[...f.querySelectorAll('.pro-item-row')].map(r=>({id:r.querySelector('[data-item]').value,q:Number(r.querySelector('[data-quantity]').value)}));if(!items.length||items.some(i=>!i.id))throw Error('Pilih barang sewa.');if(d.end<d.start)throw Error('Periksa tanggal sewa.');const payload={...d,phone,items};const sig=JSON.stringify([f.dataset.kind,payload]);let retry=JSON.parse(sessionStorage.getItem('pro_direct_retry')||'null');if(retry?.sig!==sig){payload.id=crypto.randomUUID();payload.token=crypto.randomUUID();retry={sig,payload};sessionStorage.setItem('pro_direct_retry',JSON.stringify(retry))}const result=await act(f.dataset.kind,retry.payload);if(f.dataset.kind==='quotation'){sessionStorage.removeItem('pro_direct_retry');await open('quotations');documentView(result.id)}else{const doc=await act('offer',{order_id:retry.payload.id,valid_until:d.valid_until});sessionStorage.removeItem('pro_direct_retry');await open('quotations');documentView(doc.id)}}}catch(err){if(msg)msg.textContent=err.message}finally{working=false;b.disabled=false}},true);document.addEventListener('input',e=>{if(e.target.closest('#proDirectForm'))estimate();if(e.target.id==='proJournalSearch'){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-journal-search]').forEach(r=>r.hidden=!r.dataset.journalSearch.includes(q))}});document.addEventListener('change',e=>{if(e.target.id==='quotationCustomer'){const c=quotationCustomers.find(c=>c.id===e.target.value),f=document.querySelector('#proDirectForm');if(c&&f){f.elements.name.value=c.name||'';f.elements.phone.value=c.phone||'';f.elements.email.value=c.email||''}}if(e.target.closest('#proDirectForm')){estimate();if(['start','end'].includes(e.target.name))loadProducts()}});
